/* Mermaid grammar for the self-hosted Prism on chartforgex.com. Written for this site (MIT, same as the site). */
Prism.languages.mermaid={comment:{pattern:/%%.*/,greedy:!0},string:{pattern:/"(?:\\.|[^"\\\r\n])*"/,greedy:!0},"class-name":{pattern:/^(\s*)(?:flowchart|graph|sequenceDiagram|classDiagram(?:-v2)?|stateDiagram(?:-v2)?|erDiagram|gantt|pie|journey|gitGraph|mindmap|timeline|quadrantChart|requirementDiagram|C4(?:Context|Container|Component|Dynamic|Deployment)|sankey(?:-beta)?|xychart(?:-beta)?|block(?:-beta)?|packet(?:-beta)?|kanban|architecture(?:-beta)?|radar(?:-beta)?|treemap(?:-beta)?|ishikawa|venn|wardley|cynefin|zenuml)\b/m,lookbehind:!0},keyword:/\b(?:title|section|dateFormat|axisFormat|tickInterval|excludes|includes|todayMarker|participant|actor|loop|alt|else|opt|par|and|critical|break|rect|end|note|over|left of|right of|activate|deactivate|autonumber|subgraph|direction|class|classDef|style|linkStyle|click|state|x-axis|y-axis|bar|line|accTitle|accDescr|showData|commit|branch|checkout|merge|cherry-pick|done|active|crit|milestone|after|TB|TD|BT|LR|RL)\b/,date:{pattern:/\b\d{4}-\d{2}-\d{2}\b/,alias:"number"},number:/\b\d+(?:\.\d+)?(?:ms|[smhdw])?\b/,operator:/<-->|<==>|-\.->|==>|-->>|->>|--[x)o>]|-[x)]|---|-->|->|=>|\.\.>|<\|--|\*--|o--|\|\|--|\}o--|\}\|--|<--/,punctuation:/[[\](){}:;,|]/};
